// Forma de objeto pensada para ser estendida ou implementada: interface
interface Repositorio {
  guardar(chave: string, valor: string): void;
  ler(chave: string): string | undefined;
}

// União, tupla e função com nome: type
type Resultado = "ok" | "erro";
type ParChaveValor = [string, string];
type Transformador = (entrada: string) => string;

const memoria = new Map<string, string>();

const repo: Repositorio = {
  guardar: (chave, valor) => {
    memoria.set(chave, valor);
  },
  ler: (chave) => memoria.get(chave),
};

repo.guardar("lingua", "pt-PT");

const r: Resultado = repo.ler("lingua") === undefined ? "erro" : "ok";
const par: ParChaveValor = ["lingua", "pt-PT"];
const maiusculas: Transformador = (e) => e.toUpperCase();

console.log(r, par[1], maiusculas("ok")); // "ok" "pt-PT" "OK"

interface Ponto {
  x: number;
  y: number;
}

type PontoAlias = {
  x: number;
  y: number;
};

function distancia(p: { x: number; y: number }): number {
  return Math.sqrt(p.x ** 2 + p.y ** 2);
}

const p1: Ponto = { x: 3, y: 4 };
const p2: PontoAlias = { x: 6, y: 8 };

console.log(distancia(p1)); // 5
console.log(distancia(p2)); // 10
console.log(distancia({ x: 0, y: 1 })); // 1

