interface Livro {
  titulo: string;
  autor: string;
  paginas: number;
}

type LivroAlias = {
  titulo: string;
  autor: string;
  paginas: number;
};

function resumo(l: Livro): string {
  return `${l.titulo}, de ${l.autor} (${l.paginas} páginas)`;
}

const comInterface: Livro = { titulo: "Ensaio", autor: "Saramago", paginas: 310 };
const comAlias: LivroAlias = { titulo: "Jangada", autor: "Saramago", paginas: 366 };

console.log(resumo(comInterface)); // "Ensaio, de Saramago (310 páginas)"
console.log(resumo(comAlias)); // "Jangada, de Saramago (366 páginas)"

const trocado: LivroAlias = comInterface;
console.log(trocado.paginas); // 310

type Prioridade = "baixa" | "media" | "alta";
type Milissegundos = number;
type IntervaloDeTempo = [inicio: number, fim: number];
type Formatador = (valor: number) => string;

interface Tarefa {
  id: number;
  titulo: string;
  prioridade: Prioridade;
  duracao: Milissegundos;
  janela: IntervaloDeTempo;
}

const formatarMs: Formatador = (v) => `${v} ms`;

const tarefa: Tarefa = {
  id: 1,
  titulo: "Rever contrato",
  prioridade: "alta",
  duracao: 1500,
  janela: [0, 3600000],
};

console.log(tarefa.prioridade, formatarMs(tarefa.duracao), tarefa.janela[1]);
// "alta" "1500 ms" 3600000

