// @ts-expect-error o nome Definicoes fica duplicado: o type alias não se funde
type Definicoes = { idioma: string };

export {};

// Conjunto fechado de valores: type
type Ambiente = "dev" | "prod";

// Forma de objeto que outros módulos podem estender: interface
interface LeituraDoApp {
  versao: string;
  ambiente: Ambiente;
}

// Só a interface se funde com um tipo global já declarado noutro sítio
declare global {
  interface Window {
    __APP__?: LeituraDoApp;
  }
}

export function versaoOuOmissao(omissao: string): string {
  return window.__APP__?.versao ?? omissao;
}

export function eProducao(): boolean {
  return window.__APP__?.ambiente === "prod";
}
